CREATE OR ALTER PROCEDURE [dbo].[uspDeliveryExecution_GetAll] (
	@SearchText NVARCHAR(MAX) = NULL
	, @DeliveryOrderId UNIQUEIDENTIFIER = NULL
	, @DeliveryRouteId UNIQUEIDENTIFIER = NULL
	, @Status NVARCHAR(MAX) = NULL
	, @DepartedAt DATETIME2 = NULL
	, @ArrivedAt DATETIME = NULL
	, @DeliveredAt DATETIME = NULL
	, @DriverName NVARCHAR(MAX) = NULL
	, @VehicleCode NVARCHAR(MAX) = NULL
	, @Note NVARCHAR(MAX) = NULL
	, @Page INT = 1
	, @PageSize INT = 10
	, @SortField NVARCHAR(100) = NULL
	, @SortOrder NVARCHAR(20) = NULL)
AS
BEGIN
	SET NOCOUNT ON;
	IF @Page IS NULL OR @Page < 1 SET @Page = 1;
	IF @PageSize IS NULL OR @PageSize < 1 SET @PageSize = 10;
	IF @PageSize > 1000 SET @PageSize = 1000;

	;WITH TempResult AS
	(
		SELECT
			t.[Id]
			, t.[DeliveryOrderId]
			, j1.[DeliveryNo] AS [DeliveryOrderName]
			, t.[DeliveryRouteId]
			, j2.[Name] AS [DeliveryRouteName]
			, t.[Status]
			, t.[DispatchedAt]
			, t.[ArrivedAt]
			, t.[DeliveredAt]
			, t.[Remark]
			, t.[DepartedAt]
			, t.[DriverName]
			, t.[VehicleCode]
			, t.[Note]
			, t.[CreatedDate]
		FROM [dbo].[DeliveryExecution] AS t
		LEFT JOIN [dbo].[DeliveryOrder] AS j1 ON j1.[Id] = t.[DeliveryOrderId]
		LEFT JOIN [dbo].[DeliveryRoute] AS j2 ON j2.[Id] = t.[DeliveryRouteId]
		WHERE (ISNULL(@SearchText, '') = '' OR t.[DriverName] LIKE CONCAT('%', @SearchText, '%') OR t.[VehicleCode] LIKE CONCAT('%', @SearchText, '%'))
			AND (@DeliveryOrderId IS NULL OR t.[DeliveryOrderId] = @DeliveryOrderId)
			AND (@DeliveryRouteId IS NULL OR t.[DeliveryRouteId] = @DeliveryRouteId)
			AND (ISNULL(@Status, '') = '' OR t.[Status] = @Status)
			AND (@DepartedAt IS NULL OR t.[DepartedAt] = @DepartedAt)
			AND (@ArrivedAt IS NULL OR t.[ArrivedAt] = @ArrivedAt)
			AND (@DeliveredAt IS NULL OR t.[DeliveredAt] = @DeliveredAt)
			AND (ISNULL(@DriverName, '') = '' OR t.[DriverName] LIKE CONCAT('%', @DriverName, '%'))
			AND (ISNULL(@VehicleCode, '') = '' OR t.[VehicleCode] LIKE CONCAT('%', @VehicleCode, '%'))
			AND (ISNULL(@Note, '') = '' OR t.[Note] LIKE CONCAT('%', @Note, '%'))
			AND t.IsDeleted = 0
	),
	TempCount (TotalRow) AS (SELECT COUNT(*) FROM TempResult)
	SELECT r.*, c.TotalRow
	FROM TempResult AS r CROSS JOIN TempCount AS c
	ORDER BY
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'deliveryOrderId' THEN r.[DeliveryOrderId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'deliveryOrderId' THEN r.[DeliveryOrderId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'deliveryOrderName' THEN r.[DeliveryOrderName] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'deliveryOrderName' THEN r.[DeliveryOrderName] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'deliveryRouteId' THEN r.[DeliveryRouteId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'deliveryRouteId' THEN r.[DeliveryRouteId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'deliveryRouteName' THEN r.[DeliveryRouteName] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'deliveryRouteName' THEN r.[DeliveryRouteName] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'status' THEN r.[Status] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'status' THEN r.[Status] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'dispatchedAt' THEN r.[DispatchedAt] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'dispatchedAt' THEN r.[DispatchedAt] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'arrivedAt' THEN r.[ArrivedAt] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'arrivedAt' THEN r.[ArrivedAt] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'deliveredAt' THEN r.[DeliveredAt] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'deliveredAt' THEN r.[DeliveredAt] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'remark' THEN r.[Remark] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'remark' THEN r.[Remark] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'departedAt' THEN r.[DepartedAt] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'departedAt' THEN r.[DepartedAt] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'driverName' THEN r.[DriverName] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'driverName' THEN r.[DriverName] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'vehicleCode' THEN r.[VehicleCode] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'vehicleCode' THEN r.[VehicleCode] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'note' THEN r.[Note] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'note' THEN r.[Note] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END DESC,
		r.[CreatedDate] DESC
	OFFSET (@PageSize * (@Page - 1)) ROWS FETCH NEXT @PageSize ROWS ONLY
	OPTION (RECOMPILE);
